class VelocityVerlet():
    def __init__(self, dt, n_steps, jobname, write, Tempr, initfile, method=['qchem', 'readenergy.txt']):
        self.submit = importlib.import_module('VV_8_{}'.format(method[0]))
        self.method = method
        self.n_steps = int(n_steps)
        os.system('date > time.txt')
        self.jobname = jobname[0]
        self.comname = '{}{}'.format(jobname[1], jobname[2])
        self.fchkname = '{}{}'.format(jobname[3], jobname[2])
        self.getens = self.whichenread()
        self.n = []
        self.mass = []
        self.dt = float(dt)*fs2au #scale time to au
        self.tau = float(Tempr[0])*fs2au #*41.3413733365614 old hardcode const
        self.en_thermo = bool(Tempr[2])
        self.write = int(write[0])
        self.tempxyz = write[1]

        # qi aus xyz schreiben
        self.qi = []
        #atoms, pos = reader.get_coords('{0}.xyz'.format(self.jobname))
        atoms, pos, self.vi, self.N = self.load_inits(initfile)
        for i in pos[0]:
            for j in i:
                self.qi.append(j)
        
        self.qi = np.array(self.qi)
        # alle Atomsymbole in n packen (aus .xyz-file)
        for i in atoms:
            self.n.append(element_d[i])
            self.mass = np.append(self.mass, element_m[int(i)-1])
        self.mg = np.sum(self.mass)
        self.qi = self.rem_schwerpunkt(self.qi)

        data = self.calculator(self.qi)
        self.vi = self.rem_trans_rot(self.vi, self.qi)
        self.T_soll = float(Tempr[1])
        self.thermometer()
        #self.vi = self.vi * np.sqrt(self.T_soll/self.T) do not scale velocities
        self.thermometer()
        
        # Errechnung des Gradienten
        self.gradient = self.grad(data)
        #self.gradient, self.dipol_moment = self.grad(data)
        self.ai = self.grad_to_a(self.gradient)
        self.writer(0)

    def calculator(self, q): # schreibt aktuelle Koordinaten in temp.xyz und gibt Rechnung an Gaussian. Gibt anschließend daraus errechneten Gradienten zurück.
        with open('temp.xyz', 'w') as f:
            if self.method[0] == 'gaussian': #temp.xyz without first 2 lines for gaussian
                for i in range(self.N):
                    f.write('{0:<2s} {1[0]:>20.16f} {1[1]:>20.16f} {1[2]:>20.16f} \n'.format(self.n[i], q[3*i:3*i+3]*aulen))
            else:
                f.write('{}\n\n'.format(self.N))
                for i in range(self.N):
                    f.write('{0:<2s} {1[0]:>20.16f} {1[1]:>20.16f} {1[2]:>20.16f} \n'.format(self.n[i], q[3*i:3*i+3]*aulen))
        
        self.data = self.submit.calc(self.comname, self.tempxyz, self.N, self.n, q, self.fchkname, self.getens, aulen)

        '''if self.method[0] == 'gaussian':
            
            os.system('g16 {0}.com {0}.log'.format(self.comname))
            with open('neut_stru.xyz', 'w') as f:
                for i in range(self.N):
                    f.write('{0:<2s} {1[0]:>20.16f} {1[1]:>20.16f} {1[2]:>20.16f} \n'.format(self.n[i], q[3*i:3*i+3]*aulen))
            os.system('formchk forceneut.chk forceneut.fchk')
            cp = Checkpoint('forceneut.fchk')
            data = cp.parseCheckpointFile() '''

        if self.method[0] == 'qchem': #implement qchem parser
            os.system('xyz2qchem temp.xyz geom 1')
            os.system('qchem -nt 40 force.inp force.inp.out > qchem_env_settings')
            cp = Checkpoint('force.fchk')
            data = cp.parseCheckpointFile()

        elif self.method[0] == 'orca': #implement orca parser
            with open('neut_stru.xyz', 'w') as f:
                for i in range(self.N):
                    f.write('{0:<2s} {1[0]:>20.16f} {1[1]:>20.16f} {1[2]:>20.16f} \n'.format(self.n[i], q[3*i:3*i+3]*aulen))
            os.system('orca {0}.inp > {0}.out'.format(self.comname))
            data = orp.getengrads('neut.engrad', ['gradients'])

        return data

    def grad(self, data):
        grad = self.data['gradient']
        #dipolm = data['dipole_moment']
        if self.method[0] == 'orca':
            grad = data['gradient']
            dip = orp.getdip('neut.out')
        return grad#, dipolm

    def grad_to_a(self, grad): # Umrechnung der Gradienten in Beschleunigung
        return -grad/np.repeat(self.mass, 3)

    def v_plus_1(self):         # errechnet und setzt v+1
        self.v_new = self.vi+(self.ai+self.a_new)/2*self.dt

    def q_plus_1(self):         # errechnet und setzt q+1
        self.q_new = self.qi+self.vi*self.dt+self.ai/2*self.dt**2

    def rem_schwerpunkt(self, q):# gibt Schwerpunktskoordinate zurück
        com = np.zeros(3)
        for m_i, r_i in zip(self.mass, q.reshape(-1, 3)):
            com += m_i*r_i
        com = com/self.mg
        return q-np.tile(com, len(q)//3)

    def rem_impuls(self, v):    # gibt v-Gesammtimpuls
        imp = v*np.repeat(self.mass, 3)
        impg = np.sum(imp.reshape(-1, 3), axis = 0)
        return v-np.tile(impg, len(v)//3)/self.mg

    def drehimpuls(self, q, v): # gibt Gesammtdrehimpuls zurück
        L = np.zeros(3)
        for i in range(len(self.mass)):
            L += self.mass[i]*np.cross(q[i*3:i*3+3], v[i*3:i*3+3])
        return L

    def traegheitsmoment(self, q):# gibt Trägheitsmoment zurück
        I=np.zeros((3,3))
        Emat=np.identity(3)
        for i in range(len(self.mass)):
            I+=self.mass[i]*(np.inner(q[i*3:i*3+3],q[i*3:i*3+3])*Emat-np.outer(q[i*3:i*3+3], q[i*3:i*3+3]))
        return I

    def v_winkel(self, traeg, dreh): # gibt Winkelgeschwindigkeit zurück
       return np.linalg.pinv(traeg).dot(dreh)

    def rem_rot(self, v, q, omega) : # zieht Winkelgeschwindigkeit von v ab und gibt dann v zurück
        vv = v.reshape(-1, 3)-np.cross(omega, q.reshape(-1, 3))
        return(vv.flatten())

    def rem_trans_rot(self, v, q): #elliminiert Rotation und Translation von v, gibt dann v zurück
        vv = self.rem_impuls(v)
        dreh = self.drehimpuls(q, vv)
        traeg = self.traegheitsmoment(q)
        omega = self.v_winkel(traeg, dreh)
        vv = self.rem_rot(vv, q, omega)
        return vv

    # Temperatur des Ensembles

    def thermometer(self):           # gibt Temperatur des Moleküls zurück
        self.ekin = 0
        for i in range(self.N):
            self.ekin += 0.5*self.mass[i]*np.linalg.norm(self.vi[i*3:i*3+3])**2
        T = self.ekin/(3*self.N*kbinau)#3.1667217297955e-6)
        self.T = T

    def change_v(self, v):          # gibt v*s zurück, mit s als Korrekturfaktor - siehe Berendsen Thermostat
        if self.en_thermo == True:   # enable thermostate
            v = v * np.sqrt(1+self.dt/self.tau * ((self.T_soll/self.T) - 1))
        return v #no thermostate# v * np.sqrt(1+self.dt/self.tau * ((self.T_soll/self.T) - 1))

    # Schreibefunktionen der errechneten Werte

    def append_file(self, q, time, opt): # schreibt _dynamics.xyz-file, enhalten: Atomkoordinaten für vmd Darstellung
        with open('{0}_dynamics.xyz'.format(self.jobname), opt) as f:
            f.write(str(self.N)+ '\n\n')
            for i in range(self.N):
                f.write('{0:<2s} {1[0]:>20.16f} {1[1]:>20.16f} {1[2]:>20.16f} \n'.format(self.n[i], q[3*i:3*i+3]*0.5291772109))
    def append_more(self, q, v, time, opt): # schreibt _dynamics.out-file, enthalten: Atomkoordinaten und Geschwindigkeiten
        with open('{}_dynamics.out'.format(self.jobname), opt) as f:
            f.write(str(self.N)+ '\n\n')
            for i in range(self.N):
                f.write('{0:<2s} {1[0]:>20.16f} {1[1]:>20.16f} {1[2]:>20.16f} \n'.format(self.n[i], q[3*i:3*i+3]))
            for i in range(self.N):
                f.write('{0[0]:>20.16f} {0[1]:>20.16f} {0[2]:>20.16f} \n'.format(v[3*i:3*i+3]))
    
    def write_energy(self, time):
        if self.method[0] == 'gaussian':
            wrst = '{}'.format(round(time/fs2au, 8))
            for i in self.getens:
                wrst = ''
                #wrst = '{}\t{}'.format(wrst, self.get_Energy('forceneut.fchk', i))
            with open('{0}_Energy.out'.format(self.jobname), 'a') as f:
                f.write('{}\n'.format(wrst))
        elif self.method[0] == 'qchem':
            pass # only necessary for post HF Methods like MP, CCSD, CI, ... (NOT DFT), since Total Energy is the Energy required.
    
    def write_dipol(self, dipol_moment, time):
        with open(self.jobname+'_dipol_moment.out', 'a') as f:
            f.write('\n{0:<20.3f}{1[0]:<19.16f} {1[1]:<19.16f} {1[2]:<19.16f} {2:<19.16f} {3:<19.16f}'.format(time/fs2au, dipol_moment, self.T, self.ekin)) #timetoau /= 41.3413733365614

    # bewegt das Molekül, lößt die Eliminierung der Translation und rotation aus

    def propagate(self, counter): # setzt die Berechnung und das Schreiben der Werte (also quasi das komplette Script) in Gang
        self.q_plus_1()
        self.q_new = self.rem_schwerpunkt(self.q_new)
        self.a_new = self.grad(self.calculator(self.q_new))
        #self.a_new, self.dipol_moment = self.grad(self.calculator(self.q_new))
        self.a_new = self.grad_to_a(self.a_new)
        self.v_plus_1()
        self.v_new = self.rem_trans_rot(self.v_new, self.q_new)
        self.qi = self.q_new
        self.vi = self.v_new
        self.thermometer()
        self.vi = self.change_v(self.v_new)
        self.thermometer()
        self.ai = self.a_new
        self.writer(counter)
        
    # schreibt die Errechneten Daten in die Dateien

    def writer(self, counter):
        if self.write == 0:
            self.append_file(self.qi, counter*self.dt, 'a')
        elif self.write == 1:
            self.append_more(self.qi, self.vi, counter*self.dt, 'a')
            self.write_energy(counter*self.dt)
            self.append_file(self.qi, counter*self.dt, 'a')
        elif self.write == 2:
            self.append_more(self.qi, self.vi, counter*self.dt, 'a')
            self.write_energy(counter*self.dt)
            self.append_file(self.qi, counter*self.dt, 'a')
            #self.write_dipol(self.dipol_moment, counter*self.dt)
    
    # startet die Simulation

    def simulate(self):
        for i in range(self.n_steps):
            self.propagate(i+1)
            os.system('date >> time.txt')

    def get_Energy(self, filen, search):
        with open(filen) as f:
            a = f.readlines()
            for i in a:
                if search in i:
                    return(float(i.split(' ')[-1]))

    def load_inits(self, initfile): #load samplet positions and velocities
        with open(initfile, 'r') as f:
            atoms = []
            pos = [[]]
            vs = []
            N = int(f.readline())
            for i in range(N):
                rd = list(filter(None, f.readline().split(' ')))
                atoms.append(element_d_rev[rd[0]])
                pos[0].append([float(rd[1]), float(rd[2]), float(rd[3])])
            for i in range(N):
                rd = list(filter(None, f.readline().split(' ')))
                for j in range(3):
                    vs.append(float(rd[j]))
            return atoms, pos, vs, N
    
    def whichenread(self): # init the _Energy.out file with its col-axis 
        with open(self.method[1]) as f:
            data = f.readlines()
        read = False
        i = 1
        readen = []
        quit = False
        while i < len(data) and quit == False:
            if self.method[0] in data[i] and read == False:
                read = True
            elif read == True:
                if data[i] == '\n' or '#' in data[i]:
                    quit = True
                else:
                    readen.append(data[i].split('\n')[0])
            i += 1
        with open('{0}_Energy.out'.format(self.jobname), 'w') as f:
            f.write('time[fs]' + '\t')
            for i in readen:
                f.write(i + '\t')
            f.write('\n')
        return readen

def get_in(ending):
    files = os.listdir()
    for i in files:
        if ending in i:
            return i 
